// spec: specs/contact-login-return.md (4.4) · кейс: .qa/tests/contact-login-return/CONTACT-AUTH-15.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение; в попапе — только крестик / «המשך בלי הרשמה».
import { test, expect } from '@playwright/test';
import {
  prepareGuest, loginPopup, readRedirectAfterLogin, expectPlainAuth, LISTING_ID, LISTING_URL, LOAD,
} from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Отказ от входа — адрес возврата и намерение очищаются', () => {
  for (const [label, button] of [['крестик', 'Close'], ['«המשך בלי הרשמה»', 'המשך בלי הרשמה']] as const) {
    test(`Попап: ${label} → возврат не записан → обычный /auth без «להתעניין בעסקים» #a88c1c @android @prod-safe`, async ({ page }) => {
      await prepareGuest(page);
      await page.goto(LISTING_URL);

      await page.getByRole('button', { name: 'הצג מספר טלפון' }).first().click({ timeout: LOAD.timeout });
      const popup = loginPopup(page);
      await expect(popup, 'открылся попап входа').toBeVisible(LOAD);

      await popup.getByRole('button', { name: button }).click();

      await expect(popup, 'попап закрылся').toBeHidden();
      const url = new URL(page.url());
      expect(url.pathname, 'остались на объявлении').toBe('/businessdetail');
      expect(url.searchParams.get('id'), 'то же объявление').toBe(LISTING_ID);
      expect(await readRedirectAfterLogin(page), 'redirectAfterLogin не записан').toBeNull();

      await page.goto('/auth');
      await expectPlainAuth(page, `обычный /auth после «${button}»`);
    });
  }
});
